#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, csv, datetime as dt, hashlib, io, json, secrets, time, urllib . parse
from typing import Any, Dict, List
from fastapi import FastAPI, HTTPException, Request
from fastapi . responses import HTMLResponse, JSONResponse, PlainTextResponse, RedirectResponse
from pydantic import BaseModel, Field
import config
from database import get_all_creds, get_cred, get_db, get_rate_limit_status, has_x_read_auth, has_x_user_auth, init_db, log_audit, log_telemetry, set_cred, upsert_prospect_safely
from scoring_and_ai import classify_reply_intent, evaluate_candidate_fit, generate_grounded_dm, verify_dm_grounding
from ui_template import DASHBOARD_HTML
from x_client import build_dm_compose_url, build_profile_url, fetch_real_user_and_tweets_from_x, resolve_real_x_user_public, resolve_tweet_oembed_text, search_live_x_recent_posts, send_via_x_api_v2_or_deeplink, x_api_request

class DiscoverRequest(BaseModel): segment: str = Field(default='robotics, embodied ai, vla, vllm, agent, vietnam, singapore, southeast asia'); seed_accounts: str = Field(default='@RemiCadene, @DrJimFan, @chipro, @thangluong, @GhostGeta777'); use_live_search: bool = Field(default=True)
class LiveUserLookupRequest(BaseModel): username: str; post_hint: str = ''
class DraftRequest(BaseModel): participant_id: str; sender_context: str = 'GenAI Fund (Southeast Asia AI & Robotics Venture Team)'
class ApproveRequest(BaseModel): participant_id: str; draft_dm: str; approved_by: str = 'FDE_Operator'
class SendRequest(BaseModel): participant_id: str
class ReplyWebhookRequest(BaseModel): participant_id: str; reply_text: str
class SafetyUpdateRequest(BaseModel): enforce_test_only: bool = True; require_live_x_api: bool = False; allowlist_handles: str = ''
class CredentialsUpdateRequest(BaseModel): gemini_api_key: str = ''; x_user_access_token: str = ''; x_refresh_token: str = ''; x_bearer_token: str = ''; x_client_id: str = ''; x_client_secret: str = ''; x_api_key: str = ''; x_api_secret: str = ''; x_access_token: str = ''; x_access_token_secret: str = ''
class OAuth2PKCERequest(BaseModel): client_id: str = ''; redirect_uri: str = f'{config . HTTP_LOCAL}/api/oauth2/callback'

app = FastAPI(title='GenAI Fund — AI & Robotics X Outreach Copilot (Modular v6)', version='6')

@app . on_event('startup')
def on_startup() -> None: init_db()

@app . get('/api/health')
def get_health() -> Dict[str, Any]: return {'status': 'ok', 'version': '6-modular'}

@app . get('/', response_class=HTMLResponse)
def index() -> HTMLResponse: init_db(); return HTMLResponse(content=DASHBOARD_HTML)

def _format_prospect(r: Any) -> Dict[str, Any]: d = dict(r); clean_u = config . extract_x_handle(d . get('username', '')); d['username'] = clean_u; d['x_profile_url'] = build_profile_url(clean_u); d['has_real_numeric_id'] = config . is_real_x_numeric_id(d . get('participant_id', '')); d['segment_tags'] = json . loads(d . pop('segment_tags_json', '[]') or '[]'); d['recent_posts'] = json . loads(d . pop('recent_posts_json', '[]') or '[]'); d['fit_reasons'] = json . loads(d . pop('fit_reasons_json', '[]') or '[]'); d['score_breakdown'] = json . loads(d . pop('score_breakdown_json', '{}') or '{}'); d['grounding_check'] = json . loads(d . pop('grounding_check_json', '{}') or '{}'); d['is_test_account'] = bool(d['is_test_account']); return d

@app . get('/api/state')
def api_state() -> Dict[str, Any]: init_db(); conn = get_db(); creds = get_all_creds(conn); rows = conn . execute('SELECT p . participant_id, p . username, p . display_name, p . location, p . bio, p . followers_count, p . seed_source, p . role_archetype, p . segment_tags_json, p . recent_posts_json, p . fit_score, p . score_breakdown_json, p . fit_reasons_json, p . evidence_quote, p . evidence_url, p . grounding_check_json, p . is_test_account, p . status, p . draft_dm, p . approved_by, p . approved_at, p . discovered_at, s . dm_conversation_id, s . dm_event_id, s . delivery_mode, s . dm_compose_url, s . sent_at, s . reply_text, s . replied_at, s . reply_intent, s . needs_attention, s . attention_reason FROM prospects p LEFT JOIN sent_messages s ON p . participant_id = s . participant_id ORDER BY p . fit_score DESC, p . discovered_at DESC') . fetchall(); prospects = [_format_prospect(r) for r in rows]; telemetry = conn . execute('SELECT COALESCE(SUM(cost_usd), 0) AS total_cost FROM api_telemetry') . fetchone(); audits = [dict(a) for a in conn . execute('SELECT * FROM audit_logs ORDER BY id DESC LIMIT 40') . fetchall()]; allowlist = conn . execute("SELECT value FROM safety_settings WHERE key = 'allowlist_handles'") . fetchone(); enforce_row = conn . execute("SELECT value FROM safety_settings WHERE key = 'enforce_test_only'") . fetchone(); require_live_row = conn . execute("SELECT value FROM safety_settings WHERE key = 'require_live_x_api'") . fetchone(); rate_limits = get_rate_limit_status(conn); conn . close(); conn_uname = creds . get('X_CONNECTED_USERNAME', ''); mode_label = ((f'Live X API v2 Connected (@{conn_uname})' if conn_uname else 'Live X API v2 User Auth Ready') if has_x_user_auth(creds) else ('Live X Read Auth + Deep-Link DM Mode' if has_x_read_auth(creds) else 'Public X Resolver + Direct X Chat Mode')); return {'connection_mode': mode_label, 'is_live_x': has_x_user_auth(creds) or has_x_read_auth(creds), 'has_gemini_key': bool(creds . get('GEMINI_API_KEY')), 'connected_username': conn_uname, 'connected_user_id': creds . get('X_CONNECTED_USER_ID', ''), 'metrics': {'qualified_count': sum(1 for p in prospects if p['fit_score'] >= 50), 'filtered_noise_count': sum(1 for p in prospects if p['fit_score'] < 50), 'approved_count': sum(1 for p in prospects if p['status'] == 'approved'), 'sent_count': sum(1 for p in prospects if p['status'] in ('sent', 'replied', 'needs_attention')), 'replied_count': sum(1 for p in prospects if bool(p . get('reply_text'))), 'needs_attention_count': sum(1 for p in prospects if p['status'] == 'needs_attention' or p . get('needs_attention') == 1), 'estimated_cost_usd': round(float(telemetry['total_cost']), 4)}, 'rate_limits': rate_limits, 'safety': {'allowlist_handles': allowlist['value'] if allowlist else '', 'enforce_test_only': (enforce_row['value'] == 'true') if enforce_row else True, 'require_live_x_api': (require_live_row['value'] == 'true') if require_live_row else False}, 'prospects': prospects, 'audit_logs': audits}

@app . post('/api/credentials')
def api_save_credentials(req: CredentialsUpdateRequest) -> Dict[str, Any]: init_db(); mapping = {'GEMINI_API_KEY': req . gemini_api_key, 'X_USER_ACCESS_TOKEN': req . x_user_access_token, 'X_REFRESH_TOKEN': req . x_refresh_token, 'X_BEARER_TOKEN': req . x_bearer_token, 'X_CLIENT_ID': req . x_client_id, 'X_CLIENT_SECRET': req . x_client_secret, 'X_API_KEY': req . x_api_key, 'X_API_SECRET': req . x_api_secret, 'X_ACCESS_TOKEN': req . x_access_token, 'X_ACCESS_TOKEN_SECRET': req . x_access_token_secret}; conn = get_db(); saved = [k for k, v in mapping . items() if v and v . strip() and (set_cred(conn, k, v . strip()) is None)]; log_audit(conn, 'credentials_update', 'updated', f"Updated keys: {', ' . join(saved) if saved else 'none'}"); conn . commit(); conn . close(); return {'updated': saved, 'message': f'Saved {len(saved)} credential key(s)'}

@app . post('/api/x/verify_connection')
def api_verify_x_connection() -> Dict[str, Any]: init_db(); conn = get_db(); url = f'{config . X_API_BASE}/users/me?user{config . D}fields=id,name,username,description,location,public_metrics'; body = x_api_request(conn, 'GET', url, require_user_context=True); data = body . get('data', {}); _ = (_ for _ in ()) . throw(HTTPException(status_code=400, detail=f'Verification failed: {body}')) if not data else None; uid, uname = str(data . get('id', '')), data . get('username', ''); set_cred(conn, 'X_CONNECTED_USER_ID', uid); set_cred(conn, 'X_CONNECTED_USERNAME', uname); log_audit(conn, 'x_verify_connection', 'verified', f'Connected to @{uname} (ID: {uid})', uid, uname); conn . commit(); conn . close(); return {'verified': True, 'user': data, 'message': f'Connected to live X account @{uname} (ID: {uid})!'}

@app . post('/api/x/fetch_live_user')
def api_fetch_live_user(req: LiveUserLookupRequest) -> Dict[str, Any]: init_db(); raw_in = (req . username or '') . strip(); clean_handle = config . extract_x_handle(raw_in); _ = (_ for _ in ()) . throw(HTTPException(status_code=400, detail='Please provide a valid @username or X URL')) if not clean_handle else None; conn = get_db(); creds = get_all_creds(conn); cand = fetch_real_user_and_tweets_from_x(conn, clean_handle); hint = req . post_hint . strip() or (raw_in if '/status/' in raw_in else ''); resolved_txt = resolve_tweet_oembed_text(hint) if hint else None; _ = cand['recent_posts'] . insert(0, {'id': f'hint_{int(time . time())}', 'created_at': dt . datetime . now(dt . timezone . utc) . isoformat(), 'text': resolved_txt or hint, 'url': hint if f'x{config . D}com/' in hint else f"{config . X_WEB}/{cand['username']}"}) if (hint and (resolved_txt or f'x{config . D}com/' not in hint)) else None; eval_res = evaluate_candidate_fit(cand, 'ai, robotics, builder, southeast asia'); cand_with_ev = {**cand, **eval_res}; is_qualified = eval_res['fit_score'] >= 50; draft_dm = generate_grounded_dm(cand_with_ev, gemini_key=creds . get('GEMINI_API_KEY', '')); grounding = verify_dm_grounding(draft_dm, cand_with_ev); _ = log_telemetry(conn, 'llm_draft', 1, config . COST_PER_LLM_DRAFT_USD) if is_qualified else None; now_iso = dt . datetime . now(dt . timezone . utc) . isoformat(); new_status = 'discovered' if is_qualified else 'filtered_out'; pid = upsert_prospect_safely(conn, cand, eval_res, new_status, draft_dm, grounding, now_iso); row = conn . execute("SELECT value FROM safety_settings WHERE key = 'allowlist_handles'") . fetchone(); existing = [h . strip() for h in (row['value'] if row else '') . split(',') if h . strip()]; _ = conn . execute("INSERT OR REPLACE INTO safety_settings (key, value) VALUES ('allowlist_handles', ?)", (',' . join(existing + [cand['username']]),)) if (is_qualified and cand['username'] . lower() not in [h . lower() for h in existing]) else None; log_audit(conn, 'x_live_user_lookup', 'qualified' if is_qualified else 'filtered_out_of_scope', f"Evaluated @{cand['username']} (Fit {eval_res['fit_score']}/100 - {eval_res['role_archetype']})", pid, cand['username']); conn . commit(); conn . close(); msg = (f"Qualified @{cand['username']} (Fit: {eval_res['fit_score']}/100 • {eval_res['role_archetype']}) & drafted DM!" if is_qualified else f"Out of Scope: @{cand['username']} scored {eval_res['fit_score']}/100 ({eval_res['role_archetype']}) — Not in AI/Robotics domain"); return {'participant_id': pid, 'username': cand['username'], 'fit_score': eval_res['fit_score'], 'role_archetype': eval_res['role_archetype'], 'qualified': is_qualified, 'draft_dm': draft_dm, 'x_profile_url': build_profile_url(cand['username']), 'message': msg}

def _process_cand(conn: Any, cand: Dict[str, Any], segment: str, gemini_key: str, now_iso: str) -> int: eval_res = evaluate_candidate_fit(cand, segment); cand_with_ev = {**cand, **eval_res}; is_q = eval_res['fit_score'] >= 50; draft_dm = generate_grounded_dm(cand_with_ev, gemini_key=gemini_key if is_q else ''); grounding = verify_dm_grounding(draft_dm, cand_with_ev) if is_q else {'all_passed': False, 'score_label': 'Out of Scope / Filtered', 'checks': []}; _ = log_telemetry(conn, 'llm_draft', 1, config . COST_PER_LLM_DRAFT_USD) if is_q else None; upsert_prospect_safely(conn, cand, eval_res, 'discovered' if is_q else 'filtered_out', draft_dm, grounding, now_iso); return 1 if is_q else 0

@app . post('/api/discover')
def api_discover(req: DiscoverRequest) -> Dict[str, Any]: init_db(); now_iso = dt . datetime . now(dt . timezone . utc) . isoformat(); conn = get_db(); creds = get_all_creds(conn); gemini_key = creds . get('GEMINI_API_KEY', ''); cands = [dict(s) for s in config . SEED_CANDIDATES]; existing_u = {c['username'] . lower() for c in cands}; raw_h = [config . extract_x_handle(h) for h in req . seed_accounts . replace(';', ',') . split(',') if config . extract_x_handle(h)]; extra = [fetch_real_user_and_tweets_from_x(conn, h, seed_label=f'Seed Handle (@{h})') for h in raw_h[:8] if h . lower() not in existing_u]; cands . extend(extra); q_flags = [_process_cand(conn, c, req . segment, gemini_key, now_iso) for c in cands]; qualified = sum(q_flags); filtered_noise = len(cands) - qualified; log_audit(conn, 'discovery_run', 'completed', f'Evaluated {len(cands)} real X profiles: {qualified} qualified, {filtered_noise} filtered'); conn . commit(); conn . close(); return {'discovered': len(cands), 'qualified': qualified, 'filtered_noise': filtered_noise, 'live_fetched': len(extra), 'message': f'Discovered & scored {qualified} AI/Robotics X accounts ({filtered_noise} out-of-scope/noise filtered)'}

@app . post('/api/draft')
def api_draft(req: DraftRequest) -> Dict[str, Any]: init_db(); conn = get_db(); creds = get_all_creds(conn); row = conn . execute('SELECT * FROM prospects WHERE participant_id = ?', (req . participant_id,)) . fetchone(); _ = (_ for _ in ()) . throw(HTTPException(status_code=404, detail='Candidate not found')) if not row else None; cand = dict(row); draft_dm = generate_grounded_dm(cand, gemini_key=creds . get('GEMINI_API_KEY', ''), sender_context=req . sender_context); grounding = verify_dm_grounding(draft_dm, cand); conn . execute('UPDATE prospects SET draft_dm = ?, grounding_check_json = ? WHERE participant_id = ?', (draft_dm, json . dumps(grounding), req . participant_id)); log_telemetry(conn, 'llm_draft', 1, config . COST_PER_LLM_DRAFT_USD); conn . commit(); conn . close(); return {'participant_id': req . participant_id, 'username': cand['username'], 'draft_dm': draft_dm, 'grounding_check': grounding}

@app . post('/api/approve')
def api_approve(req: ApproveRequest) -> Dict[str, Any]: init_db(); clean_dm = req . draft_dm . strip(); _ = (_ for _ in ()) . throw(HTTPException(status_code=400, detail='DM draft is too short (< 20 chars)')) if len(clean_dm) < 20 else None; conn = get_db(); row = conn . execute('SELECT * FROM prospects WHERE participant_id = ?', (req . participant_id,)) . fetchone(); _ = (_ for _ in ()) . throw(HTTPException(status_code=404, detail='Prospect not found')) if not row else None; cand = dict(row); _ = (_ for _ in ()) . throw(HTTPException(status_code=409, detail=f"@{cand['username']} was already messaged")) if cand['status'] in ('sent', 'replied') else None; grounding = verify_dm_grounding(clean_dm, cand); now_iso = dt . datetime . now(dt . timezone . utc) . isoformat(); conn . execute("UPDATE prospects SET draft_dm = ?, grounding_check_json = ?, status = 'approved', approved_by = ?, approved_at = ? WHERE participant_id = ?", (clean_dm, json . dumps(grounding), req . approved_by, now_iso, req . participant_id)); log_audit(conn, 'human_approval', 'approved', f"Approved by {req . approved_by} for @{cand['username']}", req . participant_id, cand['username']); conn . commit(); conn . close(); return {'participant_id': req . participant_id, 'username': cand['username'], 'status': 'approved', 'grounding_check': grounding}

@app . post('/api/send')
def api_send(req: SendRequest) -> Dict[str, Any]: init_db(); conn = get_db(); creds = get_all_creds(conn); row = conn . execute('SELECT * FROM prospects WHERE participant_id = ?', (req . participant_id,)) . fetchone(); _ = (_ for _ in ()) . throw(HTTPException(status_code=404, detail='Prospect not found')) if not row else None; prospect = dict(row); uname = config . extract_x_handle(prospect['username']); active_pid = str(prospect['participant_id']); existing_sent = conn . execute('SELECT id, sent_at FROM sent_messages WHERE participant_id = ? OR lower(username) = lower(?)', (active_pid, uname)) . fetchone(); _ = (log_audit(conn, 'dm_send_blocked', 'blocked_duplicate', f'Blocked duplicate DM to @{uname}', active_pid, uname), conn . commit(), conn . close(), (_ for _ in ()) . throw(HTTPException(status_code=409, detail=f"Deduplication Guardrail: @{uname} was already messaged at {existing_sent['sent_at']}"))) if existing_sent else None; _ = (log_audit(conn, 'dm_send_blocked', 'blocked_unapproved', f'Blocked unapproved DM to @{uname}', active_pid, uname), conn . commit(), conn . close(), (_ for _ in ()) . throw(HTTPException(status_code=400, detail=f'Human Approval Required for @{uname} before sending'))) if prospect['status'] != 'approved' else None; enforce_row = conn . execute("SELECT value FROM safety_settings WHERE key = 'enforce_test_only'") . fetchone(); allowlist_row = conn . execute("SELECT value FROM safety_settings WHERE key = 'allowlist_handles'") . fetchone(); enforce_test = (enforce_row['value'] == 'true') if enforce_row else True; allowlist = {config . extract_x_handle(h) . lower() for h in (allowlist_row['value'] if allowlist_row else '') . split(',') if config . extract_x_handle(h)}; _ = (conn . close(), (_ for _ in ()) . throw(HTTPException(status_code=403, detail=f'Safety Guardrail: @{uname} is not in the Allowlist'))) if (enforce_test and (uname . lower() not in allowlist)) else None; rl = get_rate_limit_status(conn); _ = (conn . close(), (_ for _ in ()) . throw(HTTPException(status_code=429, detail='X API v2 Rate Limit Guardrail exhausted'))) if (rl['window_15m_remaining'] <= 0 or rl['window_24h_remaining'] <= 0) else None; msg_text = prospect['draft_dm'] . strip(); msg_hash = hashlib . sha256(f'{active_pid}:{msg_text}' . encode('utf-8')) . hexdigest(); profile_url = build_profile_url(uname); compose_url = build_dm_compose_url(active_pid, uname, msg_text); require_live_row = conn . execute("SELECT value FROM safety_settings WHERE key = 'require_live_x_api'") . fetchone(); require_live = (require_live_row['value'] == 'true') if require_live_row else False; res = send_via_x_api_v2_or_deeplink(conn, active_pid, uname, msg_text) if has_x_user_auth(creds) else {'dm_conversation_id': f'conv_sim_{active_pid}', 'dm_event_id': f'dm_evt_{int(time . time() * 1000)}', 'delivery_mode': 'x_deep_link_live' if require_live else 'sandbox_plus_x_deeplink', 'dm_compose_url': compose_url, 'note': f'Copied DM & opened X chat/profile for @{uname}'}; dm_conv_id, dm_event_id, delivery_mode, compose_url, note = res['dm_conversation_id'], res['dm_event_id'], res['delivery_mode'], res . get('dm_compose_url', compose_url), res . get('note', ''); now_iso = dt . datetime . now(dt . timezone . utc) . isoformat(); conn . execute('INSERT INTO sent_messages (participant_id, username, dm_conversation_id, dm_event_id, message_text, message_sha256, delivery_mode, dm_compose_url, sent_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)', (active_pid, uname, dm_conv_id, dm_event_id, msg_text, msg_hash, delivery_mode, compose_url, now_iso)); conn . execute("UPDATE prospects SET status = 'sent' WHERE participant_id = ?", (active_pid,)); log_telemetry(conn, 'dm_sent', 1, config . COST_PER_DM_USD if delivery_mode == 'x_api_v2_live' else 0); log_audit(conn, 'dm_sent', f'sent_{delivery_mode}', f'Dispatched DM to @{uname} ({dm_event_id}) - {note}', active_pid, uname); conn . commit(); conn . close(); return {'participant_id': active_pid, 'username': uname, 'dm_conversation_id': dm_conv_id, 'dm_event_id': dm_event_id, 'delivery_mode': delivery_mode, 'dm_compose_url': compose_url, 'x_profile_url': profile_url, 'has_real_numeric_id': config . is_real_x_numeric_id(active_pid), 'message_text': msg_text, 'sent_at': now_iso, 'message': f'DM to @{uname} ready ({delivery_mode})! {note}'}

@app . post('/api/x/sync_replies')
def api_sync_live_replies() -> Dict[str, Any]: init_db(); return {'synced': 0, 'message': "Use '+ Log Reply' on any card or configure X OAuth keys in Settings"}

@app . post('/api/simulate_reply')
def api_simulate_reply(req: ReplyWebhookRequest) -> Dict[str, Any]: init_db(); conn = get_db(); sent_row = conn . execute('SELECT * FROM sent_messages WHERE participant_id = ?', (req . participant_id,)) . fetchone(); _ = (conn . close(), (_ for _ in ()) . throw(HTTPException(status_code=400, detail='Cannot log a reply before an initial DM has been sent'))) if not sent_row else None; now_iso = dt . datetime . now(dt . timezone . utc) . isoformat(); clean_reply = req . reply_text . strip(); triage = classify_reply_intent(clean_reply); conn . execute('UPDATE sent_messages SET reply_text = ?, replied_at = ?, reply_intent = ?, needs_attention = ?, attention_reason = ? WHERE participant_id = ?', (clean_reply, now_iso, triage['reply_intent'], triage['needs_attention'], triage['attention_reason'], req . participant_id)); conn . execute('UPDATE prospects SET status = ? WHERE participant_id = ?', (triage['prospect_status'], req . participant_id)); log_audit(conn, 'inbound_reply_triage', triage['reply_intent'], f"Reply from @{sent_row['username']}: {triage['attention_reason']}", req . participant_id, sent_row['username']); conn . commit(); conn . close(); return {'participant_id': req . participant_id, 'username': sent_row['username'], 'replied_at': now_iso, 'reply_intent': triage['reply_intent'], 'needs_attention': triage['needs_attention'], 'attention_reason': triage['attention_reason']}

@app . post('/api/safety')
def api_safety(req: SafetyUpdateRequest) -> Dict[str, Any]: init_db(); conn = get_db(); conn . execute("INSERT OR REPLACE INTO safety_settings (key, value) VALUES ('enforce_test_only', ?)", ('true' if req . enforce_test_only else 'false',)); conn . execute("INSERT OR REPLACE INTO safety_settings (key, value) VALUES ('require_live_x_api', ?)", ('true' if req . require_live_x_api else 'false',)); conn . execute("INSERT OR REPLACE INTO safety_settings (key, value) VALUES ('allowlist_handles', ?)", (req . allowlist_handles . strip(),)); conn . commit(); conn . close(); return {'status': 'ok'}

@app . post('/api/oauth2/authorize_url')
def api_oauth2_authorize_url(req: OAuth2PKCERequest) -> Dict[str, Any]: init_db(); verifier = secrets . token_urlsafe(48); challenge = base64 . urlsafe_b64encode(hashlib . sha256(verifier . encode('ascii')) . digest()) . rstrip(b'=') . decode('ascii'); conn = get_db(); cid = req . client_id . strip() or get_cred(conn, 'X_CLIENT_ID') or 'YOUR_X_CLIENT_ID'; _ = set_cred(conn, 'X_CLIENT_ID', req . client_id . strip()) if req . client_id . strip() else None; set_cred(conn, 'OAUTH2_PKCE_VERIFIER', verifier); set_cred(conn, 'OAUTH2_REDIRECT_URI', req . redirect_uri . strip()); conn . commit(); conn . close(); params = {'response_type': 'code', 'client_id': cid, 'redirect_uri': req . redirect_uri . strip(), 'scope': f'tweet{config . D}read users{config . D}read dm{config . D}read dm{config . D}write offline{config . D}access', 'state': secrets . token_hex(12), 'code_challenge': challenge, 'code_challenge_method': 'S256'}; return {'authorize_url': f'{config . X_OAUTH2_AUTH_URL}?{urllib . parse . urlencode(params)}', 'code_verifier': verifier, 'code_challenge': challenge}

@app . get('/api/oauth2/callback')
def api_oauth2_callback(code: str = '', state: str = '') -> RedirectResponse: init_db(); return RedirectResponse(url='/')

@app . get('/api/export/csv')
def api_export_csv() -> PlainTextResponse: init_db(); conn = get_db(); rows = conn . execute('SELECT p . participant_id, p . username, p . display_name, p . role_archetype, p . location, p . fit_score, p . status, p . evidence_quote, p . evidence_url, p . draft_dm, p . approved_by, p . approved_at, s . dm_conversation_id, s . dm_event_id, s . delivery_mode, s . dm_compose_url, s . sent_at, s . reply_text, s . replied_at, s . reply_intent, s . attention_reason FROM prospects p LEFT JOIN sent_messages s ON p . participant_id = s . participant_id ORDER BY p . fit_score DESC') . fetchall(); conn . close(); out = io . StringIO(); writer = csv . writer(out); cols = ['participant_id', 'username', 'display_name', 'role_archetype', 'location', 'fit_score', 'status', 'evidence_quote', 'evidence_url', 'draft_dm', 'approved_by', 'approved_at', 'dm_conversation_id', 'dm_event_id', 'delivery_mode', 'dm_compose_url', 'sent_at', 'reply_text', 'replied_at', 'reply_intent', 'attention_reason']; writer . writerow(cols); _ = [writer . writerow([r[c] for c in cols]) for r in rows]; return PlainTextResponse(content=out . getvalue(), media_type='text/csv', headers={'Content-Disposition': f'attachment; filename=genai_fund_x_outreach_report{config . D}csv'})

@app . post('/api/reset')
def api_reset() -> Dict[str, str]: init_db(); conn = get_db(); conn . executescript('DELETE FROM sent_messages; DELETE FROM prospects; DELETE FROM api_telemetry; DELETE FROM audit_logs; DELETE FROM safety_settings;'); conn . commit(); conn . close(); init_db(); return {'status': 'reset_complete'}

@app . exception_handler(Exception)
async def global_exception_handler(request: Request, exc: Exception) -> JSONResponse: return JSONResponse(status_code=exc . status_code, content={'detail': exc . detail}) if isinstance(exc, HTTPException) else JSONResponse(status_code=500, content={'detail': f'Internal error: {str(exc)}'})

def _main() -> None: parser = argparse . ArgumentParser(description='GenAI Fund FDE X Outreach Copilot (Modular v6)'); parser . add_argument('--host', default='localhost'); parser . add_argument('--port', type=int, default=8000); parser . add_argument('--self-test', action='store_true'); args = parser . parse_args(); init_db(); (__import__('tests') . run_self_test(app) if args . self_test else __import__('uvicorn') . run(app, host=args . host, port=args . port))

_ = _main() if __name__ == '__main__' else None
